CREATE TABLE IF NOT EXISTS hrm_payroll_cost_rule (id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY, entity_id bigint, employee_id bigint, prior_rule_id bigint, version int,
 effective_from date, effective_to date, parts LONGTEXT, evidence varchar(1000), status varchar(32), request_key varchar(100), request_snapshot LONGTEXT,
 employer_cost decimal(20,2), submitted_by bigint, reviewed_by bigint, reviewed_time datetime, review_reason varchar(1000), creator varchar(64) DEFAULT '', create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, updater varchar(64) DEFAULT '', update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted bit NOT NULL DEFAULT FALSE, tenant_id bigint NOT NULL DEFAULT 0, UNIQUE KEY uk_cost_rule_request(tenant_id,request_key), UNIQUE KEY uk_cost_rule_version(tenant_id,entity_id,employee_id,version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS hrm_payroll_cost_report (id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY, batch_id bigint, run_id bigint, version int, status varchar(32), input_snapshot LONGTEXT, result_snapshot LONGTEXT,
 source_digest varchar(64), reason varchar(1000), computed_by bigint, reviewed_by bigint, reviewed_time datetime, review_reason varchar(1000), creator varchar(64) DEFAULT '', create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, updater varchar(64) DEFAULT '', update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted bit NOT NULL DEFAULT FALSE, tenant_id bigint NOT NULL DEFAULT 0, UNIQUE KEY uk_cost_report_version(tenant_id,batch_id,version)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS hrm_payroll_cost_event (id bigint NOT NULL AUTO_INCREMENT PRIMARY KEY, target_id bigint, actor_id bigint, kind varchar(32), action varchar(32), reason varchar(1000), snapshot LONGTEXT, creator varchar(64) DEFAULT '', create_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, updater varchar(64) DEFAULT '', update_time datetime NOT NULL DEFAULT CURRENT_TIMESTAMP, deleted bit NOT NULL DEFAULT FALSE, tenant_id bigint NOT NULL DEFAULT 0) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
SET @parent=(SELECT id FROM system_menu WHERE path='/hrm-payroll' AND deleted=0 LIMIT 1);
INSERT INTO system_menu(name,permission,type,parent_id,path,icon,component,component_name) SELECT '薪酬成本分摊','hrm:payroll:cost:query',2,@parent,'cost','ep:data-analysis','hrm/payroll/cost/index','HrmPayrollCost' WHERE @parent IS NOT NULL AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='hrm:payroll:cost:query' AND deleted=0);
SET @cost=(SELECT id FROM system_menu WHERE permission='hrm:payroll:cost:query' AND deleted=0 LIMIT 1);
INSERT INTO system_menu(name,permission,type,parent_id,path,icon,component,component_name) SELECT '成本规则与报表准备','hrm:payroll:cost:update',3,@cost,'','','','' WHERE @cost IS NOT NULL AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='hrm:payroll:cost:update' AND deleted=0);
INSERT INTO system_menu(name,permission,type,parent_id,path,icon,component,component_name) SELECT '独立复核','hrm:payroll:cost:approve',3,@cost,'','','','' WHERE @cost IS NOT NULL AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='hrm:payroll:cost:approve' AND deleted=0);
INSERT INTO system_menu(name,permission,type,parent_id,path,icon,component,component_name) SELECT '成本报表导出','hrm:payroll:cost:export',3,@cost,'','','','' WHERE @cost IS NOT NULL AND NOT EXISTS(SELECT 1 FROM system_menu WHERE permission='hrm:payroll:cost:export' AND deleted=0);
